insert into public.questions (id, difficulty, type, topic, question, answer, alternatives, options, query, sample_tables, tokens, distractors, hint, explanation, schema_tables) values
(1, 'easy', 'write-sql', 'WHERE', 'Show all employees from the Sales department.', 'SELECT * FROM employees WHERE department = ''Sales'';', '{}'::text[], null, null, null, null, '{}'::text[], 'Filter rows with WHERE; text values go in single quotes.', 'WHERE keeps only the rows where the condition is true. Text values like ''Sales'' go in single quotes and must match the stored value''s case exactly.', array['employees']::text[]),
(2, 'easy', 'multiple-choice', 'SELECT', 'Which query returns every column of the products table?', 'SELECT * FROM products', '{}'::text[], array['SELECT * FROM products', 'SELECT % FROM products', 'SELECT ALL COLUMNS FROM products', 'GET * FROM products']::text[], null, null, null, '{}'::text[], null, 'The asterisk * is shorthand for ''all columns''. % is only a wildcard inside LIKE patterns, and GET isn''t a SQL command.', array['products']::text[]),
(3, 'easy', 'fix-query', 'SELECT', 'This query should list every employee, but it won''t run. Fix it.', 'SELECT * FROM employees;', '{}'::text[], null, 'SELEC * FORM employees;', null, null, '{}'::text[], 'Two keywords are misspelled.', 'Keywords must be spelled exactly: SELECT picks the columns and FROM names the table. A single typo in a keyword is a syntax error.', array['employees']::text[]),
(4, 'easy', 'write-sql', 'SELECT', 'Show the name and price of every product.', 'SELECT name, price FROM products;', '{}'::text[], null, null, null, null, '{}'::text[], 'Name the columns after SELECT, separated by a comma.', 'List the columns you want after SELECT, separated by commas; they come back in the order you list them. Picking only the columns you need is clearer than SELECT *.', array['products']::text[]),
(5, 'easy', 'drag-drop', 'WHERE', 'Arrange the pieces to list all Gold-tier customers.', 'SELECT * FROM customers WHERE tier = ''Gold''', '{}'::text[], null, null, null, array['SELECT *', 'FROM customers', 'WHERE tier = ''Gold''']::text[], '{}'::text[], null, 'A query reads SELECT → FROM → WHERE: choose the columns, name the table, then filter the rows. WHERE always comes after FROM.', array['customers']::text[]),
(6, 'easy', 'multiple-choice', 'DISTINCT', 'Which query returns unique departments?', 'SELECT DISTINCT department FROM employees', '{}'::text[], array['SELECT DISTINCT department FROM employees', 'SELECT department FROM employees', 'SELECT UNIQUE department FROM employees', 'SELECT department DISTINCT FROM employees']::text[], null, null, null, '{}'::text[], null, 'DISTINCT goes right after SELECT and removes duplicate rows from the result. Without it you get one row per employee; UNIQUE is a constraint keyword, not a query option.', array['employees', 'departments']::text[]),
(7, 'easy', 'predict-output', 'SELECT', 'What does this query return?', 'Ana | 50000
Ben | 62000
Cara | 58000', '{}'::text[], array['Ana | 50000
Ben | 62000
Cara | 58000', 'Ana | Sales | 50000
Ben | HR | 62000
Cara | Sales | 58000', '50000 | Ana
62000 | Ben
58000 | Cara', 'Ana | 50000
Cara | 58000
Ben | 62000']::text[], 'SELECT name, salary FROM employees ORDER BY name', '[{"name":"employees","columns":["name","department","salary"],"rows":[["Ana","Sales",50000],["Ben","HR",62000],["Cara","Sales",58000]]}]'::jsonb, null, '{}'::text[], null, 'Only the listed columns come back, in the order you list them: name, then salary. department isn''t selected, and ORDER BY name sorts the rows alphabetically.', array['employees']::text[]),
(8, 'easy', 'write-sql', 'ORDER BY', 'List all products (every column), cheapest first.', 'SELECT * FROM products ORDER BY price;', '{}'::text[], null, null, null, null, '{}'::text[], 'Sort with ORDER BY; think about the default direction.', 'ORDER BY sorts the result, and ascending (lowest first) is the default, so ASC is optional. Without ORDER BY, row order is not guaranteed.', array['products']::text[]),
(9, 'easy', 'multiple-choice', 'ORDER BY', 'ORDER BY price with no ASC or DESC sorts the rows…', 'Lowest price first', '{}'::text[], array['Lowest price first', 'Highest price first', 'In the order they were inserted', 'In random order']::text[], null, null, null, '{}'::text[], null, 'ASC (ascending) is the default direction, so the lowest values come first. Add DESC to sort highest first.', '{}'::text[]),
(10, 'easy', 'drag-drop', 'SELECT', 'Arrange the pieces to show every column of every order.', 'SELECT * FROM orders', '{}'::text[], null, null, null, array['SELECT', '*', 'FROM', 'orders']::text[], '{}'::text[], null, 'The simplest query is SELECT <columns> FROM <table>. * means all columns, and FROM names the table to read.', array['orders']::text[]),
(11, 'easy', 'write-sql', 'DISTINCT', 'List each city our customers live in, with no duplicates.', 'SELECT DISTINCT city FROM customers;', '{}'::text[], null, null, null, null, '{}'::text[], 'One keyword after SELECT removes repeats.', 'SELECT DISTINCT removes duplicate rows, so each city appears once no matter how many customers live there.', array['customers']::text[]),
(12, 'easy', 'fix-query', 'WHERE', 'This should list all shipped orders, but it errors. Fix it.', 'SELECT * FROM orders WHERE status = ''shipped'';', '{}'::text[], null, 'SELECT * FROM orders WHERE status = shipped;', null, null, '{}'::text[], 'How does SQL tell a text value from a column name?', 'Without quotes, shipped is read as a column name, so PostgreSQL complains it doesn''t exist. Text values must be wrapped in single quotes: ''shipped''.', array['orders']::text[]),
(13, 'easy', 'predict-output', 'WHERE', 'What does this query return?', 'Lamp
Rug', '{}'::text[], array['Lamp
Rug', 'Lamp
Mug
Rug', 'Book
Mug
Pen', 'Rug']::text[], 'SELECT name FROM products WHERE price > 20 ORDER BY name', '[{"name":"products","columns":["name","price"],"rows":[["Book",12],["Lamp",35],["Mug",20],["Pen",5],["Rug",48]]}]'::jsonb, null, '{}'::text[], null, '> means strictly greater than, so Mug at exactly 20 is excluded (>= would include it). Only Lamp (35) and Rug (48) pass.', array['products']::text[]),
(14, 'easy', 'multiple-choice', 'LIMIT', 'What does LIMIT 3 at the end of a query do?', 'Returns at most 3 rows', '{}'::text[], array['Returns at most 3 rows', 'Skips the first 3 rows', 'Returns only 3 columns', 'Returns rows with id up to 3']::text[], null, null, null, '{}'::text[], null, 'LIMIT caps how many rows come back: at most 3, or fewer if the result is smaller. Skipping rows is OFFSET''s job.', '{}'::text[]),
(15, 'easy', 'write-sql', 'LIMIT', 'Take a quick peek at the orders table: show any 5 rows, all columns.', 'SELECT * FROM orders LIMIT 5;', '{}'::text[], null, null, null, null, '{}'::text[], 'Cap the number of rows at the end of the query.', 'LIMIT n returns at most n rows. Without ORDER BY you get whichever 5 rows the database finds first, which is fine for a quick peek.', array['orders']::text[]),
(16, 'easy', 'drag-drop', 'DISTINCT', 'Arrange the pieces to list each product category once, A–Z.', 'SELECT DISTINCT category FROM products ORDER BY category', '{}'::text[], null, null, null, array['SELECT DISTINCT category', 'FROM products', 'ORDER BY category']::text[], array['SELECT UNIQUE category']::text[], null, 'DISTINCT follows SELECT to drop duplicate values, and ORDER BY goes last to sort them. UNIQUE isn''t valid in a SELECT list.', array['products']::text[]),
(17, 'easy', 'multiple-choice', 'SELECT', 'Which clause tells SQL which table to read from?', 'FROM', '{}'::text[], array['FROM', 'SELECT', 'WHERE', 'INTO']::text[], null, null, null, '{}'::text[], null, 'FROM names the table the data comes from. SELECT picks the columns, WHERE filters rows, and INTO is used when inserting or creating tables.', '{}'::text[]),
(18, 'easy', 'predict-output', 'DISTINCT', 'What does this query return?', 'Oslo
