Rome', 'Oslo']::text[], 'SELECT DISTINCT city FROM customers ORDER BY city', '[{"name":"customers","columns":["name","city"],"rows":[["Ann","Paris"],["Bob","Rome"],["Cid","Paris"],["Dan","Oslo"],["Eve","Rome"]]}]'::jsonb, null, '{}'::text[], null, 'DISTINCT keeps one copy of each value, so Paris and Rome appear once each. Oslo is already unique, so all three cities are listed.', array['customers']::text[]),
(19, 'easy', 'write-sql', 'SELECT', 'HR wants the name, job_title and salary of every employee, in that column order.', 'SELECT name, job_title, salary FROM employees;', '{}'::text[], null, null, null, null, '{}'::text[], 'Three columns, comma-separated, in the order given.', 'Columns come back in exactly the order you list them after SELECT. Commas separate the columns, and no comma goes before FROM.', array['employees']::text[]),
(20, 'easy', 'fix-query', 'ORDER BY', 'This should list employee names and salaries, highest salary first. Fix it.', 'SELECT name, salary FROM employees ORDER BY salary DESC;', '{}'::text[], null, 'SELECT name, salary FROM employees SORT BY salary DESC;', null, null, '{}'::text[], 'SQL''s sorting clause starts with a different word.', 'SQL sorts with ORDER BY; SORT BY isn''t a PostgreSQL clause. DESC then puts the highest salaries first.', array['employees']::text[]),
(21, 'easy', 'write-sql', 'SELECT', 'Show every customer''s name, with the output column labelled customer_name.', 'SELECT name AS customer_name FROM customers;', '{}'::text[], null, null, null, null, '{}'::text[], 'Use AS after the column to rename it in the output.', 'AS gives a column an alias in the result only; the table itself is unchanged. The AS keyword is optional, but it makes the intent clear.', array['customers']::text[]),
(22, 'easy', 'multiple-choice', 'SELECT', 'What does AS do in SELECT name AS customer_name FROM customers?', 'Labels the result column customer_name', '{}'::text[], array['Labels the result column customer_name', 'Renames the column in the table', 'Filters rows by customer name', 'Creates a customer_name table']::text[], null, null, null, '{}'::text[], null, 'AS creates an alias: a temporary name for the output column. The stored table and its column names are untouched.', array['customers']::text[]),
(23, 'easy', 'fix-query', 'LIMIT', 'This should show any 10 products, but PostgreSQL rejects it. Fix it.', 'SELECT * FROM products LIMIT 10;', '{}'::text[], null, 'SELECT TOP 10 * FROM products;', null, null, '{}'::text[], 'PostgreSQL limits rows with a clause at the end.', 'TOP is SQL Server syntax. PostgreSQL uses LIMIT, placed at the end of the query.', array['products']::text[]),
(24, 'easy', 'write-sql', 'WHERE', 'Find all employees earning more than 70000.', 'SELECT * FROM employees WHERE salary > 70000;', '{}'::text[], null, null, null, null, '{}'::text[], 'Numbers don''t need quotes.', 'Comparison operators (>, <, >=, <=, =, <>) compare numbers without quotes. > is strict, so a salary of exactly 70000 is excluded.', array['employees']::text[]),
(25, 'easy', 'drag-drop', 'ORDER BY', 'Arrange the pieces to list product names and prices, most expensive first.', 'SELECT name, price FROM products ORDER BY price DESC', '{}'::text[], null, null, null, array['SELECT name, price', 'FROM products', 'ORDER BY price DESC']::text[], array['ORDER BY price ASC']::text[], null, 'DESC sorts from highest to lowest; ASC (the default) would put the cheapest first.', array['products']::text[]),
(26, 'easy', 'multiple-choice', 'WHERE', 'Which condition finds orders placed on or after 1 January 2024?', 'WHERE order_date >= ''2024-01-01''', '{}'::text[], array['WHERE order_date >= ''2024-01-01''', 'WHERE order_date > ''2024-01-01''', 'WHERE order_date => ''2024-01-01''', 'WHERE order_date >= 2024-01-01']::text[], null, null, null, '{}'::text[], null, '>= means ''on or after'', while > would skip 1 January itself. Date literals need quotes (unquoted, 2024-01-01 is just arithmetic), and => isn''t a comparison operator.', array['orders']::text[]),
(27, 'easy', 'predict-output', 'ORDER BY', 'What does this query return?', 'Desk
