(28, 'easy', 'write-sql', 'ORDER BY', 'Show customers'' name and signup_date, newest signups first.', 'SELECT name, signup_date FROM customers ORDER BY signup_date DESC;', '{}'::text[], null, null, null, null, '{}'::text[], 'Newest first means descending.', 'Dates sort chronologically, so DESC puts the most recent dates first. Ascending order would show the oldest signups first.', array['customers']::text[]),
(29, 'easy', 'multiple-choice', 'DISTINCT', 'SELECT DISTINCT city, country FROM customers removes duplicates of…', 'Each city + country pair', '{}'::text[], array['Each city + country pair', 'The city column only', 'The country column only', 'Rows where city equals country']::text[], null, null, null, '{}'::text[], null, 'DISTINCT applies to the whole selected row, not just the first column. Two rows count as duplicates only if both city and country match.', array['customers']::text[]),
(30, 'easy', 'drag-drop', 'LIMIT', 'Arrange the pieces to show the 3 cheapest products.', 'SELECT * FROM products ORDER BY price LIMIT 3', '{}'::text[], null, null, null, array['SELECT *', 'FROM products', 'ORDER BY price', 'LIMIT 3']::text[], '{}'::text[], null, 'Sort first, then cut: ORDER BY price puts the cheapest on top and LIMIT 3 keeps just those. LIMIT always comes after ORDER BY.', array['products']::text[]),
(31, 'easy', 'write-sql', 'LIMIT', 'Show the 10 most recent orders (all columns).', 'SELECT * FROM orders ORDER BY order_date DESC LIMIT 10;', '{}'::text[], null, null, null, null, '{}'::text[], 'Sort newest first, then cap the rows.', '''Most recent'' needs a sort: ORDER BY order_date DESC puts the newest first, then LIMIT 10 keeps the top ten. LIMIT without ORDER BY would give arbitrary rows.', array['orders']::text[]),
(32, 'easy', 'fix-query', 'SELECT', 'This should show each customer''s name and email, but it errors. Fix it.', 'SELECT name, email FROM customers;', '{}'::text[], null, 'SELECT name, email, FROM customers;', null, null, '{}'::text[], 'Look just before FROM.', 'Commas go between columns, never after the last one. A trailing comma makes PostgreSQL expect another column and fail at FROM.', array['customers']::text[]),
(33, 'easy', 'predict-output', 'LIMIT', 'What does this query return?', 'Cy | 91000
Eli | 85000', '{}'::text[], array['Cy | 91000
Eli | 85000', 'Ava | 72000
Ben | 58000', 'Ben | 58000
