(39, 'easy', 'write-sql', 'SELECT', 'Show each product''s name and its stock value (price * stock), labelled stock_value.', 'SELECT name, price * stock AS stock_value FROM products;', array['SELECT name, stock * price AS stock_value FROM products;']::text[], null, null, null, null, '{}'::text[], 'Multiply two columns in the SELECT list, then alias it.', 'SELECT can compute new columns from existing ones, row by row. Give computed columns an alias with AS so the result has a readable name.', array['products']::text[]),
(40, 'easy', 'fix-query', 'DISTINCT', 'This should list each unique city + country combination. Fix it.', 'SELECT DISTINCT city, country FROM customers;', '{}'::text[], null, 'SELECT city, DISTINCT country FROM customers;', null, null, '{}'::text[], 'DISTINCT has only one allowed position.', 'DISTINCT must come right after SELECT and applies to all selected columns together. It can''t be attached to a single column in the middle of the list.', array['customers']::text[]),
(41, 'easy', 'write-sql', 'WHERE', 'Find Engineering employees earning more than 90000 (all columns).', 'SELECT * FROM employees WHERE department = ''Engineering'' AND salary > 90000;', array['SELECT * FROM employees WHERE salary > 90000 AND department = ''Engineering'';']::text[], null, null, null, null, '{}'::text[], 'Combine two conditions so both must hold.', 'AND keeps a row only when both conditions are true. The order of the two conditions doesn''t change the result.', array['employees']::text[]),
(42, 'easy', 'multiple-choice', 'WHERE', 'Which condition finds customers in the Gold or Silver tier?', 'WHERE tier IN (''Gold'', ''Silver'')', '{}'::text[], array['WHERE tier IN (''Gold'', ''Silver'')', 'WHERE tier = ''Gold'' AND tier = ''Silver''', 'WHERE tier = ''Gold'' OR ''Silver''', 'WHERE tier IN ''Gold'', ''Silver''']::text[], null, null, null, '{}'::text[], null, 'IN checks a value against a parenthesised list, like several ORs. AND would need tier to be both at once (never true), and OR ''Silver'' isn''t a complete condition.', array['customers']::text[]),
(43, 'easy', 'fix-query', 'WHERE', 'This should list pending and shipped orders. Fix it.', 'SELECT * FROM orders WHERE status IN (''pending'', ''shipped'');', '{}'::text[], null, 'SELECT * FROM orders WHERE status IN ''pending'', ''shipped'';', null, null, '{}'::text[], 'IN''s list needs to be wrapped in something.', 'The value list after IN must be wrapped in parentheses: IN (''pending'', ''shipped''). Without them PostgreSQL reports a syntax error.', array['orders']::text[]),
(44, 'easy', 'write-sql', 'DISTINCT', 'List every distinct department and city combination among employees (department column first).', 'SELECT DISTINCT department, city FROM employees;', '{}'::text[], null, null, null, null, '{}'::text[], 'One DISTINCT covers all the selected columns.', 'With several columns, DISTINCT removes rows only when the whole combination repeats. Sales in London and Sales in Paris are both kept.', array['employees']::text[]),
(45, 'easy', 'drag-drop', 'ORDER BY', 'Arrange the pieces to list employees by department A–Z, highest salary first within each department.', 'SELECT name, department, salary FROM employees ORDER BY department, salary DESC', '{}'::text[], null, null, null, array['SELECT name, department, salary', 'FROM employees', 'ORDER BY department, salary DESC']::text[], array['ORDER BY salary DESC, department']::text[], null, 'The first ORDER BY column is the main sort; the next one only breaks ties within it. Each column gets its own direction, so department is ascending and salary descending.', array['employees']::text[]),
(46, 'easy', 'multiple-choice', 'ORDER BY', 'In ORDER BY department, salary DESC, how is department sorted?', 'Ascending', '{}'::text[], array['Ascending', 'Descending', 'It isn''t sorted', 'By salary only']::text[], null, null, null, '{}'::text[], null, 'ASC/DESC applies only to the column right before it. department has no keyword, so it uses the default: ascending.', '{}'::text[]),
(47, 'easy', 'predict-output', 'WHERE', 'What does this query return?', 'Hat
Scarf
Bag', '{}'::text[], array['Hat
Scarf
Bag', 'Scarf', 'Hat
Scarf', 'Scarf
Bag']::text[], 'SELECT name FROM products WHERE price BETWEEN 20 AND 30 ORDER BY price', '[{"name":"products","columns":["name","price"],"rows":[["Cap",10],["Hat",20],["Scarf",25],["Bag",30],["Coat",40]]}]'::jsonb, null, '{}'::text[], null, 'BETWEEN is inclusive on both ends: price >= 20 AND price <= 30. So Hat (20) and Bag (30) are included along with Scarf.', array['products']::text[]),
(48, 'easy', 'write-sql', 'WHERE', 'Find orders with a total_amount from 100 to 500 inclusive, using BETWEEN.', 'SELECT * FROM orders WHERE total_amount BETWEEN 100 AND 500;', array['SELECT * FROM orders WHERE total_amount >= 100 AND total_amount <= 500;']::text[], null, null, null, null, '{}'::text[], 'BETWEEN low AND high.', 'BETWEEN a AND b includes both endpoints, so it equals >= a AND <= b. Put the smaller value first, or it matches nothing.', array['orders']::text[]),
(49, 'easy', 'multiple-choice', 'DISTINCT', '10 employees work in 3 departments. How many rows does SELECT DISTINCT department FROM employees return?', '3', '{}'::text[], array['3', '10', '1', '13']::text[], null, null, null, '{}'::text[], null, 'DISTINCT returns one row per unique value, so 10 employees collapse to 3 department names.', array['employees', 'departments']::text[]),
(50, 'easy', 'drag-drop', 'DISTINCT', 'Arrange the pieces to list the countries that have Silver-tier customers, each country once.', 'SELECT DISTINCT country FROM customers WHERE tier = ''Silver''', '{}'::text[], null, null, null, array['SELECT DISTINCT country', 'FROM customers', 'WHERE tier = ''Silver''']::text[], '{}'::text[], null, 'WHERE filters the rows, then DISTINCT removes duplicate countries from what''s left. DISTINCT is still written right after SELECT.', array['customers']::text[])
on conflict (id) do nothing;

insert into public.questions (id, difficulty, type, topic, question, answer, alternatives, options, query, sample_tables, tokens, distractors, hint, explanation, schema_tables) values
(51, 'easy', 'write-sql', 'ORDER BY', 'List customers'' name, country and city, sorted by country then city (both A–Z).', 'SELECT name, country, city FROM customers ORDER BY country, city;', '{}'::text[], null, null, null, null, '{}'::text[], 'ORDER BY accepts a comma-separated list.', 'Separate multiple sort columns with commas. Rows are sorted by country first; city only decides the order among customers in the same country.', array['customers']::text[]),
(52, 'easy', 'fix-query', 'ORDER BY', 'This should list Toys products, cheapest first. Fix it.', 'SELECT * FROM products WHERE category = ''Toys'' ORDER BY price;', '{}'::text[], null, 'SELECT * FROM products ORDER BY price WHERE category = ''Toys'';', null, null, '{}'::text[], 'Clauses must appear in a fixed order.', 'Clauses have a fixed order: SELECT, FROM, WHERE, ORDER BY, LIMIT. WHERE must come before ORDER BY.', array['products']::text[]),
