(54, 'easy', 'multiple-choice', 'LIMIT', 'In ORDER BY price LIMIT 5 OFFSET 10, what does OFFSET 10 do?', 'Skips the first 10 rows', '{}'::text[], array['Skips the first 10 rows', 'Returns 10 rows', 'Starts at the row with id 10', 'Adds 10 to each price']::text[], null, null, null, '{}'::text[], null, 'OFFSET skips that many rows before LIMIT starts counting, so this returns rows 11–15 of the sorted result.', '{}'::text[]),
(55, 'easy', 'write-sql', 'LIMIT', 'Products are shown 10 per page, sorted by name. Show page 2 (all columns).', 'SELECT * FROM products ORDER BY name LIMIT 10 OFFSET 10;', array['SELECT * FROM products ORDER BY name OFFSET 10 LIMIT 10;']::text[], null, null, null, null, '{}'::text[], 'Skip one page''s worth of rows, then take a page.', 'Page 2 skips the first 10 rows (OFFSET 10) and takes the next 10 (LIMIT 10). In general, OFFSET = (page − 1) × page size.', array['products']::text[]),
(56, 'easy', 'drag-drop', 'LIMIT', 'Arrange the pieces to show the names and salaries of the 5 highest-paid employees.', 'SELECT name, salary FROM employees ORDER BY salary DESC LIMIT 5', '{}'::text[], null, null, null, array['SELECT name, salary', 'FROM employees', 'ORDER BY salary DESC', 'LIMIT 5']::text[], array['ORDER BY salary']::text[], null, 'For a top-N list, sort descending and then LIMIT. Sorting ascending would give the 5 lowest salaries instead.', array['employees']::text[]),
(57, 'easy', 'multiple-choice', 'SELECT', 'What does SELECT price * 2 FROM products do?', 'Shows doubled prices; the table is unchanged', '{}'::text[], array['Shows doubled prices; the table is unchanged', 'Doubles the prices stored in the table', 'Returns only the first 2 rows', 'Fails: SELECT can''t do math']::text[], null, null, null, '{}'::text[], null, 'SELECT only reads data: expressions are calculated for the output and stored values never change. Changing data requires UPDATE.', array['products']::text[]),
(58, 'easy', 'predict-output', 'DISTINCT', 'What does this query return?', 'Oslo | Gold
Oslo | Silver
Rome | Gold', '{}'::text[], array['Oslo | Gold
Oslo | Silver
Rome | Gold', 'Oslo
Rome', 'Oslo | Gold
Rome | Gold', 'Oslo | Gold
Oslo | Gold
Oslo | Silver
Rome | Gold
Rome | Gold']::text[], 'SELECT DISTINCT city, tier FROM customers ORDER BY city, tier', '[{"name":"customers","columns":["city","tier"],"rows":[["Oslo","Gold"],["Oslo","Gold"],["Oslo","Silver"],["Rome","Gold"],["Rome","Gold"]]}]'::jsonb, null, '{}'::text[], null, 'DISTINCT compares whole rows, so each unique (city, tier) pair appears once. Oslo shows up twice because Gold and Silver make different pairs.', array['customers']::text[]),
(59, 'easy', 'write-sql', 'WHERE', 'Find customers who are in the Gold tier or live in the country ''Canada'' (all columns).', 'SELECT * FROM customers WHERE tier = ''Gold'' OR country = ''Canada'';', array['SELECT * FROM customers WHERE country = ''Canada'' OR tier = ''Gold'';']::text[], null, null, null, null, '{}'::text[], 'Keep a row if either condition is true.', 'OR keeps a row if at least one condition is true, so Gold customers anywhere and every Canadian customer are included.', array['customers']::text[]),
(60, 'easy', 'fix-query', 'LIMIT', 'This should show the 11th–20th cheapest products. Fix it for PostgreSQL.', 'SELECT * FROM products ORDER BY price LIMIT 10 OFFSET 10;', array['SELECT * FROM products ORDER BY price OFFSET 10 LIMIT 10;']::text[], null, 'SELECT * FROM products ORDER BY price LIMIT 10, 10;', null, null, '{}'::text[], 'PostgreSQL wants a separate keyword for skipping rows.', 'The comma form LIMIT offset, count is MySQL syntax, which PostgreSQL rejects. Use LIMIT count OFFSET skip instead.', array['products']::text[]),
(61, 'easy', 'write-sql', 'WHERE', 'Find customers whose name starts with ''A'' (all columns).', 'SELECT * FROM customers WHERE name LIKE ''A%'';', '{}'::text[], null, null, null, null, '{}'::text[], 'Use a pattern with a wildcard at the end.', 'LIKE matches patterns: % stands for any run of characters, so ''A%'' means ''starts with A''. LIKE is case-sensitive in PostgreSQL.', array['customers']::text[]),
(62, 'easy', 'multiple-choice', 'WHERE', 'In a LIKE pattern, what does % match?', 'Any number of characters, even zero', '{}'::text[], array['Any number of characters, even zero', 'Exactly one character', 'At least one character', 'Only digits']::text[], null, null, null, '{}'::text[], null, '% matches any sequence of characters, including none, so ''Pro%'' also matches ''Pro'' itself. The underscore _ matches exactly one character.', '{}'::text[]),
(63, 'easy', 'fix-query', 'WHERE', 'This should find the CEO (the employee with no manager) but returns no rows. Fix it.', 'SELECT * FROM employees WHERE manager_id IS NULL;', '{}'::text[], null, 'SELECT * FROM employees WHERE manager_id = NULL;', null, null, '{}'::text[], 'Comparing with = never works for missing values.', 'NULL means ''unknown'', so = NULL is never true, not even for NULL values. Use IS NULL (or IS NOT NULL) to test for missing values.', array['employees']::text[]),
(64, 'easy', 'write-sql', 'SELECT', 'Show each employee''s name and their salary divided by 12, labelled monthly_salary.', 'SELECT name, salary / 12 AS monthly_salary FROM employees;', '{}'::text[], null, null, null, null, '{}'::text[], 'Divide in the SELECT list, then alias the result.', 'Arithmetic in SELECT is evaluated per row. salary is numeric, so the division keeps decimals; dividing two integers would drop the fraction.', array['employees']::text[]),
(65, 'easy', 'drag-drop', 'SELECT', 'Arrange the pieces to show Clothing products'' names with a 20%-off price labelled sale_price.', 'SELECT name, price * 0.8 AS sale_price FROM products WHERE category = ''Clothing''', '{}'::text[], null, null, null, array['SELECT name, price * 0.8 AS sale_price', 'FROM products', 'WHERE category = ''Clothing''']::text[], '{}'::text[], null, 'Computed columns and their aliases live in the SELECT list. Multiplying by 0.8 gives 80% of the price, i.e. 20% off.', array['products']::text[]),
(66, 'easy', 'multiple-choice', 'WHERE', 'Which condition matches ''apple'', ''Apple'' and ''APPLE''?', 'name ILIKE ''apple''', '{}'::text[], array['name ILIKE ''apple''', 'name LIKE ''apple''', 'name = ''apple''', 'name LIKE ''Apple''']::text[], null, null, null, '{}'::text[], null, 'In PostgreSQL, = and LIKE are case-sensitive. ILIKE is PostgreSQL''s case-insensitive version of LIKE.', '{}'::text[]),
(67, 'easy', 'predict-output', 'SELECT', 'What does this query return?', 'Cy | 63000
Ben | 60000
Ava | 55000', '{}'::text[], array['Cy | 63000
Ben | 60000
Ava | 55000', 'Ben | 60000
Cy | 55000
Ava | 50000', 'Ava | 55000
Ben | 60000
Cy | 63000', '63000
60000
55000']::text[], 'SELECT name, salary + bonus AS total_pay FROM employees ORDER BY total_pay DESC', '[{"name":"employees","columns":["name","salary","bonus"],"rows":[["Ava",50000,5000],["Ben",60000,0],["Cy",55000,8000]]}]'::jsonb, null, '{}'::text[], null, 'total_pay is calculated per row (salary + bonus), and ORDER BY can use that alias. Sorting DESC puts Cy''s 63000 first.', array['employees']::text[]),
(68, 'easy', 'write-sql', 'ORDER BY', 'Show each order''s id and total_amount * 0.9 labelled discounted, sorted by discounted, highest first.', 'SELECT id, total_amount * 0.9 AS discounted FROM orders ORDER BY discounted DESC;', array['SELECT id, total_amount * 0.9 AS discounted FROM orders ORDER BY total_amount * 0.9 DESC;', 'SELECT id, total_amount * 0.9 AS discounted FROM orders ORDER BY total_amount DESC;', 'SELECT id, total_amount * 0.9 AS discounted FROM orders ORDER BY 2 DESC;']::text[], null, null, null, null, '{}'::text[], 'ORDER BY can refer to a SELECT alias.', 'ORDER BY is applied after the SELECT list is computed, so it can use a column alias like discounted. WHERE runs earlier and can''t.', array['orders']::text[]),
(69, 'easy', 'multiple-choice', 'ORDER BY', 'In PostgreSQL, where do NULL cities appear with ORDER BY city (ascending)?', 'At the end', '{}'::text[], array['At the end', 'At the start', 'They''re left out', 'Scattered randomly']::text[], null, null, null, '{}'::text[], null, 'PostgreSQL sorts NULL as if it were larger than any value, so NULLs come last in ascending order and first with DESC. NULLS FIRST / NULLS LAST overrides this.', '{}'::text[]),
(70, 'easy', 'drag-drop', 'ORDER BY', 'Arrange the pieces to list the names of customers in Germany, A–Z.', 'SELECT name FROM customers WHERE country = ''Germany'' ORDER BY name', '{}'::text[], null, null, null, array['SELECT name', 'FROM customers', 'WHERE country = ''Germany''', 'ORDER BY name']::text[], '{}'::text[], null, 'WHERE filters the rows and ORDER BY sorts what''s left, and they''re written in that order too. In a basic query only LIMIT/OFFSET can follow ORDER BY.', array['customers']::text[]),
(71, 'easy', 'write-sql', 'DISTINCT', 'Which departments have employees in the city ''London''? List each department once.', 'SELECT DISTINCT department FROM employees WHERE city = ''London'';', '{}'::text[], null, null, null, null, '{}'::text[], 'Filter to London, then remove repeats.', 'WHERE keeps only London employees, then DISTINCT removes repeated department names. DISTINCT always sits right after SELECT, even when a WHERE follows.', array['employees', 'departments']::text[]),
(72, 'easy', 'fix-query', 'SELECT', 'The name column should be labelled product_name, but this query errors. Fix it.', 'SELECT name AS product_name, price FROM products;', '{}'::text[], null, 'SELECT name AS product name, price FROM products;', null, null, '{}'::text[], 'Unquoted aliases can''t contain spaces.', 'An unquoted alias must be a single word, so product name is a syntax error. Use an underscore (product_name), or double quotes if you really need a space.', array['products']::text[]),
(73, 'easy', 'predict-output', 'WHERE', 'What does this query return?', 'Ada
Dev', '{}'::text[], array['Ada
Dev', '(no rows)', 'Bo
Cy', 'Ada
Bo
Cy
Dev']::text[], 'SELECT name FROM employees WHERE manager_id IS NULL ORDER BY name', '[{"name":"employees","columns":["name","manager_id"],"rows":[["Ada",null],["Bo",1],["Cy",2],["Dev",null]]}]'::jsonb, null, '{}'::text[], null, 'IS NULL matches rows where the value is missing: Ada and Dev. Writing = NULL instead would return no rows at all.', array['employees']::text[]),
(74, 'easy', 'multiple-choice', 'LIMIT', 'Which ending returns the 2 oldest employees (highest age)?', 'ORDER BY age DESC LIMIT 2', '{}'::text[], array['ORDER BY age DESC LIMIT 2', 'ORDER BY age LIMIT 2', 'LIMIT 2 ORDER BY age DESC', 'ORDER BY age DESC OFFSET 2']::text[], null, null, null, '{}'::text[], null, 'Sort oldest first with DESC, then keep 2 rows with LIMIT. LIMIT must come after ORDER BY, and OFFSET 2 would skip the top 2 instead.', array['employees']::text[]),
(75, 'easy', 'write-sql', 'LIMIT', 'Show the name and price of the single most expensive product.', 'SELECT name, price FROM products ORDER BY price DESC LIMIT 1;', '{}'::text[], null, null, null, null, '{}'::text[], 'Sort, then keep one row.', 'Sort descending so the priciest product comes first, then LIMIT 1 keeps just that row. If several products tie, you get one of them.', array['products']::text[]),
(76, 'easy', 'drag-drop', 'DISTINCT', 'Arrange the pieces to list each Engineering job title once, A–Z.', 'SELECT DISTINCT job_title FROM employees WHERE department = ''Engineering'' ORDER BY job_title', '{}'::text[], null, null, null, array['SELECT DISTINCT job_title', 'FROM employees', 'WHERE department = ''Engineering''', 'ORDER BY job_title']::text[], array['SELECT job_title DISTINCT']::text[], null, 'DISTINCT must come directly after SELECT. The query then filters with WHERE and sorts the unique titles with ORDER BY.', array['employees']::text[]),
(77, 'easy', 'multiple-choice', 'SELECT', 'Which query gives a column an alias containing a space in PostgreSQL?', 'SELECT name AS "Full Name" FROM employees', '{}'::text[], array['SELECT name AS "Full Name" FROM employees', 'SELECT name AS ''Full Name'' FROM employees', 'SELECT name AS Full Name FROM employees', 'SELECT name AS [Full Name] FROM employees']::text[], null, null, null, '{}'::text[], null, 'PostgreSQL wraps identifiers, including aliases, in double quotes. Single quotes make a string value (rejected as an alias), and square brackets are SQL Server syntax.', array['employees']::text[]),
(78, 'easy', 'predict-output', 'DISTINCT', 'Two customers have no city (NULL). What does this query return?', 'Lima
Oslo
NULL', '{}'::text[], array['Lima
Oslo
NULL', 'Lima
Oslo', 'Lima
Oslo
NULL
NULL', 'NULL
Lima
Oslo']::text[], 'SELECT DISTINCT city FROM customers ORDER BY city', '[{"name":"customers","columns":["name","city"],"rows":[["Ann","Lima"],["Bo",null],["Cy","Oslo"],["Di","Lima"],["Ed",null]]}]'::jsonb, null, '{}'::text[], null, 'DISTINCT treats NULLs as duplicates of each other, so a single NULL row remains. In ascending order PostgreSQL sorts NULLs last.', array['customers']::text[]),
(79, 'easy', 'write-sql', 'SELECT', 'Show one column called contact that joins each customer''s name and email with a space between, using ||.', 'SELECT name || '' '' || email AS contact FROM customers;', '{}'::text[], null, null, null, null, '{}'::text[], 'Glue three pieces: name, a space, email.', '|| concatenates text in PostgreSQL; put the separator in quotes between the pieces. If either value is NULL, the whole result is NULL.', array['customers']::text[]),
(80, 'easy', 'fix-query', 'DISTINCT', 'This should list unique customer cities alphabetically, but it errors. Fix it.', 'SELECT DISTINCT city FROM customers ORDER BY city;', '{}'::text[], null, 'SELECT DISTINCT city FROM customers ORDER BY name;', null, null, '{}'::text[], 'With DISTINCT you can only sort by selected columns.', 'With SELECT DISTINCT, ORDER BY may only use expressions from the select list. After duplicates are removed there''s no single name per city to sort by.', array['customers']::text[]),
(81, 'easy', 'write-sql', 'WHERE', 'Find customers whose email ends with ''@gmail.com'' (all columns).', 'SELECT * FROM customers WHERE email LIKE ''%@gmail.com'';', '{}'::text[], null, null, null, null, '{}'::text[], 'Put the wildcard where the unknown part is.', 'Putting % at the start means ''anything before'', so the pattern matches emails that end with @gmail.com.', array['customers']::text[]),
(82, 'easy', 'multiple-choice', 'WHERE', 'WHERE department = ''Sales'' OR department = ''HR'' AND salary > 60000 returns…', 'All Sales staff, plus HR staff over 60000', '{}'::text[], array['All Sales staff, plus HR staff over 60000', 'Sales and HR staff, all over 60000', 'Only HR staff over 60000', 'Nobody: a column can''t match two values']::text[], null, null, null, '{}'::text[], null, 'AND binds tighter than OR, so this reads Sales OR (HR AND salary > 60000). Wrap the OR part in parentheses to apply the salary filter to both.', '{}'::text[]),
(83, 'easy', 'fix-query', 'ORDER BY', 'This should list orders from the largest total_amount to the smallest. Fix it.', 'SELECT id, total_amount FROM orders ORDER BY total_amount DESC;', '{}'::text[], null, 'SELECT id, total_amount FROM orders ORDER BY total_amount DESCENDING;', null, null, '{}'::text[], 'The keyword is shorter than the English word.', 'The sort keywords are the abbreviations DESC and ASC; DESCENDING isn''t valid in PostgreSQL.', array['orders']::text[]),
(84, 'easy', 'write-sql', 'ORDER BY', 'List product name and stock, lowest stock first; break ties by name A–Z.', 'SELECT name, stock FROM products ORDER BY stock, name;', '{}'::text[], null, null, null, null, '{}'::text[], 'Two sort columns, main one first.', 'The second ORDER BY column only matters when the first one ties. Both columns use the default ascending order here.', array['products']::text[]),
(85, 'easy', 'drag-drop', 'WHERE', 'Arrange the pieces to list the name and price of Electronics products priced 100 to 500 inclusive, cheapest first.', 'SELECT name, price FROM products WHERE category = ''Electronics'' AND price BETWEEN 100 AND 500 ORDER BY price', '{}'::text[], null, null, null, array['SELECT name, price', 'FROM products', 'WHERE category = ''Electronics'' AND price BETWEEN 100 AND 500', 'ORDER BY price']::text[], '{}'::text[], null, 'One WHERE can combine several conditions with AND. The AND inside BETWEEN 100 AND 500 belongs to BETWEEN, not a separate condition.', array['products']::text[]),
(86, 'easy', 'multiple-choice', 'DISTINCT', 'How does SELECT ALL city differ from SELECT DISTINCT city?', 'ALL keeps duplicates; DISTINCT removes them', '{}'::text[], array['ALL keeps duplicates; DISTINCT removes them', 'ALL also returns every column', 'They return identical results', 'DISTINCT only sorts the rows']::text[], null, null, null, '{}'::text[], null, 'ALL is the default (keep every row, duplicates included), so it''s rarely written. DISTINCT removes duplicate rows but doesn''t guarantee any sort order.', '{}'::text[]),
(87, 'easy', 'predict-output', 'WHERE', 'What does this query return?', 'Ben
Dee', '{}'::text[], array['Ben
Dee', 'Ben
Cai
Dee', 'Ava', 'Ben
Cai']::text[], 'SELECT name FROM customers WHERE tier <> ''Gold'' ORDER BY name', '[{"name":"customers","columns":["name","tier"],"rows":[["Ava","Gold"],["Ben","Silver"],["Cai",null],["Dee","Bronze"]]}]'::jsonb, null, '{}'::text[], null, 'Comparing NULL with <> gives unknown, not true, so Cai (no tier) is filtered out. Add OR tier IS NULL to keep rows with missing values.', array['customers']::text[]),
(88, 'easy', 'write-sql', 'LIMIT', 'Show just the names of the 3 most recently hired employees.', 'SELECT name FROM employees ORDER BY hire_date DESC LIMIT 3;', '{}'::text[], null, null, null, null, '{}'::text[], 'Sort by hire date, newest first, then cap.', 'You can sort by a column you don''t select. hire_date DESC puts the newest hires first, and LIMIT 3 keeps them.', array['employees']::text[]),
(89, 'easy', 'multiple-choice', 'DISTINCT', 'Every order has a unique id. Compared with SELECT * FROM orders, SELECT DISTINCT * FROM orders returns…', 'The same number of rows', '{}'::text[], array['The same number of rows', 'Fewer rows', 'Exactly one row', 'An error']::text[], null, null, null, '{}'::text[], null, 'DISTINCT compares entire rows. Because every row has a different id, no two rows are identical, so nothing is removed.', array['orders']::text[]),
(90, 'easy', 'drag-drop', 'SELECT', 'Arrange the pieces to list delivered orders'' id and total_amount (labelled amount), biggest amount first.', 'SELECT id, total_amount AS amount FROM orders WHERE status = ''delivered'' ORDER BY amount DESC', '{}'::text[], null, null, null, array['SELECT id, total_amount AS amount', 'FROM orders', 'WHERE status = ''delivered''', 'ORDER BY amount DESC']::text[], '{}'::text[], null, 'An alias defined in SELECT can be reused in ORDER BY, because sorting happens after the SELECT list is computed. WHERE can''t see aliases, so it uses the real column.', array['orders']::text[]),
(91, 'easy', 'write-sql', 'DISTINCT', 'List each customer country once, in alphabetical order.', 'SELECT DISTINCT country FROM customers ORDER BY country;', '{}'::text[], null, null, null, null, '{}'::text[], 'Remove repeats, then sort.', 'DISTINCT doesn''t guarantee any order, so add ORDER BY. With DISTINCT, the sort column must be one you selected.', array['customers']::text[]),
(92, 'easy', 'fix-query', 'DISTINCT', 'This should list each customer tier once. Fix it.', 'SELECT DISTINCT tier FROM customers;', '{}'::text[], null, 'SELECT UNIQUE tier FROM customers;', null, null, '{}'::text[], 'Wrong keyword for removing duplicates.', 'The keyword that removes duplicate rows is DISTINCT. UNIQUE is a table-constraint keyword and isn''t allowed in a SELECT list.', array['customers']::text[]),
(93, 'easy', 'predict-output', 'LIMIT', 'What does this query return?', 'Mug
Cap', '{}'::text[], array['Mug
Cap', 'Pen
Mug', 'Cap
Lamp', 'Pen
Mug
Cap']::text[], 'SELECT name FROM products ORDER BY price LIMIT 2 OFFSET 1', '[{"name":"products","columns":["name","price"],"rows":[["Pen",2],["Mug",8],["Cap",12],["Lamp",25],["Desk",140]]}]'::jsonb, null, '{}'::text[], null, 'After sorting by price, OFFSET 1 skips Pen, then LIMIT 2 takes the next two rows: Mug and Cap.', array['products']::text[]),
(94, 'easy', 'multiple-choice', 'LIMIT', 'Which is the standard-SQL form of LIMIT 5, also valid in PostgreSQL?', 'FETCH FIRST 5 ROWS ONLY', '{}'::text[], array['FETCH FIRST 5 ROWS ONLY', 'TOP 5', 'WHERE ROWNUM <= 5', 'LIMIT ROWS 5']::text[], null, null, null, '{}'::text[], null, 'FETCH FIRST n ROWS ONLY is the SQL-standard spelling, and PostgreSQL supports it alongside LIMIT. TOP is SQL Server syntax and ROWNUM is Oracle''s.', '{}'::text[]),
(95, 'easy', 'write-sql', 'WHERE', 'Find products that are out of stock (stock = 0) or have no price set (all columns).', 'SELECT * FROM products WHERE stock = 0 OR price IS NULL;', array['SELECT * FROM products WHERE price IS NULL OR stock = 0;']::text[], null, null, null, null, '{}'::text[], 'Missing values need a special test.', 'A missing price is NULL, which only IS NULL can detect. OR keeps rows that meet either condition.', array['products']::text[]),
(96, 'easy', 'drag-drop', 'LIMIT', 'Arrange the pieces to skip the 5 priciest products and show the next 5 (name and price).', 'SELECT name, price FROM products ORDER BY price DESC LIMIT 5 OFFSET 5', '{}'::text[], null, null, null, array['SELECT name, price', 'FROM products', 'ORDER BY price DESC', 'LIMIT 5 OFFSET 5']::text[], array['LIMIT 5, 5']::text[], null, 'OFFSET 5 skips the top five rows and LIMIT 5 takes the next five. The comma form LIMIT 5, 5 is MySQL-only.', array['products']::text[]),
(97, 'easy', 'multiple-choice', 'ORDER BY', 'What does ORDER BY 2 mean in SELECT name, price FROM products ORDER BY 2?', 'Sort by the 2nd selected column, price', '{}'::text[], array['Sort by the 2nd selected column, price', 'Sort by the constant value 2', 'Return only 2 rows', 'Start sorting from row 2']::text[], null, null, null, '{}'::text[], null, 'A plain number in ORDER BY refers to a position in the SELECT list, so 2 means price. It works, but column names are clearer and safer.', array['products']::text[]),
(98, 'easy', 'predict-output', 'ORDER BY', 'What does this query return?', 'Ben | NULL
