(99, 'easy', 'write-sql', 'SELECT', 'No table needed: have PostgreSQL calculate 12 * 7 in a column named result.', 'SELECT 12 * 7 AS result;', '{}'::text[], null, null, null, null, '{}'::text[], 'SELECT works without FROM.', 'In PostgreSQL, FROM is optional: SELECT can evaluate expressions on its own and returns one row. It''s handy as a quick calculator.', '{}'::text[]),
(100, 'easy', 'fix-query', 'LIMIT', 'This should show the names and prices of the 5 most expensive products. Fix it.', 'SELECT name, price FROM products ORDER BY price DESC LIMIT 5;', '{}'::text[], null, 'SELECT name, price FROM products LIMIT 5 ORDER BY price DESC;', null, null, '{}'::text[], 'Clause order matters.', 'LIMIT must come after ORDER BY: the rows are sorted first, then the top 5 are kept.', array['products']::text[])
on conflict (id) do nothing;

insert into public.questions (id, difficulty, type, topic, question, answer, alternatives, options, query, sample_tables, tokens, distractors, hint, explanation, schema_tables) values
(101, 'medium', 'multiple-choice', 'GROUP BY', 'Which clause turns many rows into one row per department, so COUNT can run once per department?', 'GROUP BY', '{}'::text[], array['GROUP BY', 'ORDER BY', 'HAVING', 'DISTINCT']::text[], null, null, null, '{}'::text[], null, 'GROUP BY collapses rows sharing a value into groups, and aggregates run once per group. DISTINCT only removes duplicate rows, and HAVING filters groups that already exist.', '{}'::text[]),
(102, 'medium', 'write-sql', 'GROUP BY', 'HR wants a headcount for each department. Return department and the number of employees, aliased headcount.', 'SELECT department, COUNT(*) AS headcount FROM employees GROUP BY department', array['SELECT department, COUNT(id) AS headcount FROM employees GROUP BY department']::text[], null, null, null, null, '{}'::text[], 'You need one row per department. Which clause builds groups?', 'GROUP BY department collapses all rows with the same department into one group, and COUNT(*) then counts the rows in each group.', array['employees']::text[]),
(103, 'medium', 'fix-query', 'COUNT', 'This should count the orders that are still pending. Fix it.', 'SELECT COUNT(*) AS pending_count FROM orders WHERE status = ''pending''', '{}'::text[], null, 'SELECT COUNT(*) AS pending_count FROM orders WHERE status = pending', null, null, '{}'::text[], 'How are text values written in SQL?', 'Text literals need single quotes. Without them PostgreSQL reads pending as a column name and fails because no such column exists.', array['orders']::text[]),
(104, 'medium', 'drag-drop', 'GROUP BY', 'Rank products by how many order lines they appear in: the 10 most-ordered product_ids, with the count as times_ordered.', 'SELECT product_id, COUNT(*) AS times_ordered FROM order_items GROUP BY product_id ORDER BY times_ordered DESC LIMIT 10', '{}'::text[], null, null, null, array['SELECT product_id, COUNT(*) AS times_ordered', 'FROM order_items', 'GROUP BY product_id', 'ORDER BY times_ordered DESC', 'LIMIT 10']::text[], '{}'::text[], null, 'Group the line items by product, count each group, sort by that count descending and keep 10. LIMIT always comes last.', array['products', 'order_items']::text[]),
(105, 'medium', 'multiple-choice', 'HAVING', 'What is the key difference between WHERE and HAVING?', 'WHERE filters rows before grouping; HAVING filters groups after', '{}'::text[], array['WHERE filters rows before grouping; HAVING filters groups after', 'HAVING filters rows before grouping; WHERE filters groups after', 'They are interchangeable; HAVING is just newer syntax', 'HAVING only works together with ORDER BY']::text[], null, null, null, '{}'::text[], null, 'WHERE removes individual rows before GROUP BY runs, so it can''t use aggregates. HAVING runs after grouping and filters whole groups, typically using aggregates like COUNT(*).', '{}'::text[]),
(106, 'medium', 'write-sql', 'COUNT', 'How many customers are in the ''Gold'' tier? Return one column aliased gold_count.', 'SELECT COUNT(*) AS gold_count FROM customers WHERE tier = ''Gold''', array['SELECT COUNT(id) AS gold_count FROM customers WHERE tier = ''Gold''']::text[], null, null, null, null, '{}'::text[], 'Filter the rows first, then count them.', 'WHERE keeps only Gold customers, then COUNT(*) counts the remaining rows. An aggregate with no GROUP BY always returns exactly one row.', array['customers']::text[]),
(107, 'medium', 'multiple-choice', 'COUNT', 'Only the CEO has a NULL manager_id. In a 50-employee table, what do COUNT(*) and COUNT(manager_id) return?', '50 and 49', '{}'::text[], array['50 and 49', '49 and 49', '50 and 50', '49 and 50']::text[], null, null, null, '{}'::text[], null, 'COUNT(*) counts rows, so it returns 50. COUNT(manager_id) counts only non-NULL values, so the CEO''s NULL is skipped: 49.', '{}'::text[]),
