FROM employees
GROUP BY city
ORDER BY city', '[{"name":"employees","columns":["name","city"],"rows":[["Ana","Paris"],["Ben","Oslo"],["Cy","Paris"],["Dee","Rome"],["Eli","Paris"]]}]'::jsonb, null, '{}'::text[], null, 'GROUP BY city makes one row per distinct city and COUNT(*) counts its rows: Paris has 3. ORDER BY city then sorts the groups alphabetically.', array['employees']::text[]),
(109, 'medium', 'write-sql', 'SUM', 'Finance wants total revenue from ''delivered'' orders. Return the sum of total_amount aliased revenue.', 'SELECT SUM(total_amount) AS revenue FROM orders WHERE status = ''delivered''', '{}'::text[], null, null, null, null, '{}'::text[], 'Filter to delivered orders, then add up the amounts.', 'SUM adds up total_amount across the rows that pass WHERE. Without GROUP BY, the whole filtered table is one group, giving a single total.', array['orders']::text[]),
(110, 'medium', 'multiple-choice', 'COUNT', 'What does each result row of this query represent?', 'A status and how many orders have it', '{}'::text[], array['A status and how many orders have it', 'A status and the sum of its order amounts', 'One order together with its status', 'The number of distinct statuses']::text[], 'SELECT status, COUNT(*)
FROM orders
GROUP BY status', null, null, '{}'::text[], null, 'GROUP BY status produces one row per status value, and COUNT(*) counts the orders that fall into each status group.', array['orders']::text[]),
(111, 'medium', 'fix-query', 'AVG', 'This should show the average quantity per product_id in order_items. Fix it.', 'SELECT product_id, AVG(quantity) AS avg_qty FROM order_items GROUP BY product_id', '{}'::text[], null, 'SELECT product_id, AVERAGE(quantity) AS avg_qty FROM order_items GROUP BY product_id', null, null, '{}'::text[], 'The function name is shorter than you might think.', 'The SQL average function is AVG. AVERAGE is the spreadsheet name, so PostgreSQL reports that the function doesn''t exist.', array['order_items']::text[]),
(112, 'medium', 'drag-drop', 'SUM', 'Total order value per status, ignoring cancelled orders.', 'SELECT status, SUM(total_amount) AS total_value FROM orders WHERE status <> ''cancelled'' GROUP BY status', '{}'::text[], null, null, null, array['SELECT status, SUM(total_amount) AS total_value', 'FROM orders', 'WHERE status <> ''cancelled''', 'GROUP BY status']::text[], '{}'::text[], null, 'WHERE removes cancelled rows before grouping, then SUM adds up total_amount for each remaining status.', array['orders']::text[]),
(113, 'medium', 'write-sql', 'AVG', 'What is the average salary across all employees? Alias it avg_salary.', 'SELECT AVG(salary) AS avg_salary FROM employees', '{}'::text[], null, null, null, null, '{}'::text[], 'One aggregate over the whole table; no grouping needed.', 'AVG(salary) averages the non-NULL salaries of every row. Without GROUP BY, the whole table is one group, so you get a single row.', array['employees']::text[]),
(114, 'medium', 'multiple-choice', 'INNER JOIN', 'What does an INNER JOIN return?', 'Only rows that have a match in both tables', '{}'::text[], array['Only rows that have a match in both tables', 'All rows of the left table, matched or not', 'All rows of both tables, matched or not', 'Every possible pairing of rows from both tables']::text[], null, null, null, '{}'::text[], null, 'An INNER JOIN keeps only row pairs that satisfy the ON condition; unmatched rows from either side are dropped. Keeping all left rows is LEFT JOIN, and every pairing is CROSS JOIN.', '{}'::text[]),
(115, 'medium', 'write-sql', 'GROUP BY', 'The pricing team wants the highest price in each product category. Return category and the top price aliased max_price.', 'SELECT category, MAX(price) AS max_price FROM products GROUP BY category', '{}'::text[], null, null, null, null, '{}'::text[], 'Pick the right aggregate, then group by category.', 'With GROUP BY category, MAX(price) is computed separately inside each category, so you get one row per category holding its most expensive price.', array['products']::text[]),
(116, 'medium', 'multiple-choice', 'GROUP BY', 'What does PostgreSQL do with this query?', 'Raises an error: name must be grouped or aggregated', '{}'::text[], array['Raises an error: name must be grouped or aggregated', 'Returns one arbitrary name per department', 'Returns every employee with their department''s count', 'Returns the alphabetically first name per department']::text[], 'SELECT department, name, COUNT(*)
FROM employees
GROUP BY department', null, null, '{}'::text[], null, 'Every SELECT column must appear in GROUP BY or be wrapped in an aggregate. A department group contains many names, so PostgreSQL refuses rather than guessing one.', array['employees']::text[]),
(117, 'medium', 'fix-query', 'GROUP BY', 'This should count employees for every department and job_title combination, but it errors. Fix it.', 'SELECT department, job_title, COUNT(*) AS staff FROM employees GROUP BY department, job_title', array['SELECT department, job_title, COUNT(*) AS staff FROM employees GROUP BY job_title, department']::text[], null, 'SELECT department, job_title, COUNT(*) AS staff FROM employees GROUP BY department', null, null, '{}'::text[], 'Every non-aggregated SELECT column must be grouped.', 'job_title isn''t inside an aggregate, so it must be listed in GROUP BY too. Otherwise PostgreSQL can''t decide which job_title to show for a department.', array['employees']::text[]),
(118, 'medium', 'predict-output', 'HAVING', 'Which orders make the cut?', '1 | 7
2 | 6', '{}'::text[], array['1 | 7
2 | 6', '2 | 6', '1 | 7
2 | 6
3 | 5', '3 | 5']::text[], 'SELECT order_id, SUM(quantity) AS units
FROM order_items
GROUP BY order_id
HAVING SUM(quantity) > 5
ORDER BY order_id', '[{"name":"order_items","columns":["order_id","quantity"],"rows":[[1,4],[1,3],[2,6],[3,2],[3,1],[3,2]]}]'::jsonb, null, '{}'::text[], null, 'HAVING tests each order''s total after grouping: 7 and 6 pass, 5 doesn''t. It doesn''t filter individual rows; that would be WHERE quantity > 5, which keeps only the single 6.', array['orders', 'order_items']::text[]),
(119, 'medium', 'drag-drop', 'GROUP BY', 'Show each department''s first and last hire dates, with the earliest first hire at the top.', 'SELECT department, MIN(hire_date) AS first_hire, MAX(hire_date) AS last_hire FROM employees GROUP BY department ORDER BY first_hire', '{}'::text[], null, null, null, array['SELECT department, MIN(hire_date) AS first_hire, MAX(hire_date) AS last_hire', 'FROM employees', 'GROUP BY department', 'ORDER BY first_hire']::text[], array['GROUP BY hire_date']::text[], null, 'MIN and MAX of a date column give the earliest and latest dates in each group. Grouping by hire_date would make one group per date instead of per department.', array['employees']::text[]),
(120, 'medium', 'write-sql', 'GROUP BY', 'For each order status, when was the earliest order placed? Return status and the earliest order_date aliased first_order.', 'SELECT status, MIN(order_date) AS first_order FROM orders GROUP BY status', '{}'::text[], null, null, null, null, '{}'::text[], 'MIN and MAX work on dates, not just numbers.', 'MIN works on any sortable type, including dates: MIN(order_date) returns the earliest date inside each status group.', array['orders']::text[]),
(121, 'medium', 'multiple-choice', 'GROUP BY', 'products has 40 rows spread across all 5 categories. How many rows does this return?', '5', '{}'::text[], array['5', '40', '8', '1']::text[], 'SELECT category, COUNT(*)
FROM products
GROUP BY category', null, null, '{}'::text[], null, 'GROUP BY returns one row per distinct value of the grouping column. Five categories means five rows, no matter how many products each one holds.', array['products']::text[]),
(122, 'medium', 'write-sql', 'HAVING', 'Marketing wants to know which countries have more than 10 customers. Return country and the count aliased customer_count.', 'SELECT country, COUNT(*) AS customer_count FROM customers GROUP BY country HAVING COUNT(*) > 10', array['SELECT country, COUNT(id) AS customer_count FROM customers GROUP BY country HAVING COUNT(id) > 10']::text[], null, null, null, null, '{}'::text[], 'Filtering on an aggregate happens after grouping.', 'WHERE runs before grouping and can''t see aggregates, so a condition on COUNT(*) goes in HAVING. PostgreSQL doesn''t let HAVING use the alias customer_count, so repeat COUNT(*).', array['customers']::text[]),
(123, 'medium', 'fix-query', 'GROUP BY', 'This should count customers per city, biggest cities first, but it''s a syntax error. Fix it.', 'SELECT city, COUNT(*) AS customer_count FROM customers GROUP BY city ORDER BY customer_count DESC', '{}'::text[], null, 'SELECT city, COUNT(*) AS customer_count FROM customers ORDER BY customer_count DESC GROUP BY city', null, null, '{}'::text[], 'Clauses must appear in a fixed order.', 'Clause order is fixed: SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY, LIMIT. ORDER BY sorts the final grouped result, so it comes after GROUP BY.', array['customers']::text[]),
(124, 'medium', 'predict-output', 'COUNT', 'One customer has no city recorded. What does this return?', '5 | 4 | 2', '{}'::text[], array['5 | 4 | 2', '5 | 5 | 3', '5 | 4 | 3', '4 | 4 | 2']::text[], 'SELECT COUNT(*) AS total, COUNT(city) AS with_city,
       COUNT(DISTINCT city) AS cities
FROM customers', '[{"name":"customers","columns":["name","city"],"rows":[["Ana","London"],["Ben","Paris"],["Cara","London"],["Dev",null],["Eve","Paris"]]}]'::jsonb, null, '{}'::text[], null, 'COUNT(*) counts all 5 rows, COUNT(city) skips Dev''s NULL (4), and COUNT(DISTINCT city) counts unique non-NULL values, London and Paris (2).', array['customers']::text[]),
(125, 'medium', 'drag-drop', 'HAVING', 'List departments whose average salary is above 75000.', 'SELECT department, AVG(salary) AS avg_salary FROM employees GROUP BY department HAVING AVG(salary) > 75000', '{}'::text[], null, null, null, array['SELECT department, AVG(salary) AS avg_salary', 'FROM employees', 'GROUP BY department', 'HAVING AVG(salary) > 75000']::text[], array['WHERE AVG(salary) > 75000']::text[], null, 'The condition is on an aggregate, so it must be HAVING, after GROUP BY. Aggregates aren''t allowed in WHERE.', array['employees', 'departments']::text[]),
(126, 'medium', 'multiple-choice', 'COUNT', 'What does COUNT(1) count?', 'Every row, exactly like COUNT(*)', '{}'::text[], array['Every row, exactly like COUNT(*)', 'Rows where the first column isn''t NULL', 'Nothing; it always returns 1', 'Only rows whose id equals 1']::text[], null, null, null, '{}'::text[], null, 'COUNT(expr) counts rows where expr is not NULL. The constant 1 is never NULL, so COUNT(1) counts every row, just like COUNT(*). It doesn''t refer to the first column.', '{}'::text[]),
(127, 'medium', 'write-sql', 'COUNT', 'How many different countries do our customers come from? Alias the result country_count.', 'SELECT COUNT(DISTINCT country) AS country_count FROM customers', '{}'::text[], null, null, null, null, '{}'::text[], 'Each country should be counted only once.', 'COUNT(DISTINCT country) counts unique non-NULL values. Plain COUNT(country) would count every customer who has a country, duplicates included.', array['customers']::text[]),
(128, 'medium', 'write-sql', 'COUNT', 'How many products in each category are in stock (stock > 0)? Return category and the count aliased in_stock_count.', 'SELECT category, COUNT(*) AS in_stock_count FROM products WHERE stock > 0 GROUP BY category', array['SELECT category, COUNT(id) AS in_stock_count FROM products WHERE stock > 0 GROUP BY category']::text[], null, null, null, null, '{}'::text[], 'The stock test applies to individual products.', 'WHERE stock > 0 removes out-of-stock rows before grouping, so COUNT(*) only counts in-stock products per category. A category with nothing in stock disappears entirely.', array['products']::text[]),
(129, 'medium', 'fix-query', 'HAVING', 'This should list supplier_ids that supply more than 20 products. Fix it.', 'SELECT supplier_id, COUNT(*) AS product_count FROM products GROUP BY supplier_id HAVING COUNT(*) > 20', '{}'::text[], null, 'SELECT supplier_id, COUNT(*) AS product_count FROM products WHERE COUNT(*) > 20 GROUP BY supplier_id', null, null, '{}'::text[], 'Aggregates can''t be filtered before the groups exist.', 'Aggregate functions are not allowed in WHERE, because WHERE runs before any groups exist. Conditions on COUNT(*) go in HAVING, after GROUP BY.', array['products']::text[]),
(130, 'medium', 'predict-output', 'SUM', 'What does this return for each order?', '1 | 25
2 | 32', '{}'::text[], array['1 | 25
2 | 32', '1 | 45
2 | 96', '1 | 3
2 | 4', '1 | 15
2 | 24']::text[], 'SELECT order_id, SUM(quantity * unit_price) AS total
FROM order_items
GROUP BY order_id
ORDER BY order_id', '[{"name":"order_items","columns":["order_id","quantity","unit_price"],"rows":[[1,2,10],[1,1,5],[2,3,4],[2,1,20]]}]'::jsonb, null, '{}'::text[], null, 'The product is computed per row first (20 + 5 for order 1, 12 + 20 for order 2) and then summed. Multiplying SUM(quantity) by SUM(unit_price) would give 45 and 96.', array['order_items']::text[]),
(131, 'medium', 'drag-drop', 'COUNT', 'Count employees older than 40 in each city, most first.', 'SELECT city, COUNT(*) AS senior_staff FROM employees WHERE age > 40 GROUP BY city ORDER BY senior_staff DESC', '{}'::text[], null, null, null, array['SELECT city, COUNT(*) AS senior_staff', 'FROM employees', 'WHERE age > 40', 'GROUP BY city', 'ORDER BY senior_staff DESC']::text[], array['GROUP BY city, age']::text[], null, 'WHERE age > 40 filters people before they are grouped, so COUNT(*) counts only the over-40s in each city. Grouping by age as well would split each city into many groups.', array['employees']::text[]),
(132, 'medium', 'multiple-choice', 'SUM', 'What happens if you run SELECT SUM(name) FROM employees?', 'An error: SUM doesn''t accept text', '{}'::text[], array['An error: SUM doesn''t accept text', 'It joins all the names into one string', 'It returns how many names there are', 'It returns 0, since names aren''t numbers']::text[], null, null, null, '{}'::text[], null, 'SUM has no version for text, so PostgreSQL rejects SUM(name) with a ''function sum(text) does not exist'' error. Use COUNT to count values or string_agg to join text.', array['employees']::text[]),
(133, 'medium', 'write-sql', 'SUM', 'Warehouse check: how many units are in stock per category? Return category and the total stock aliased total_stock.', 'SELECT category, SUM(stock) AS total_stock FROM products GROUP BY category', '{}'::text[], null, null, null, null, '{}'::text[], 'Add up (don''t count) the stock column.', 'SUM(stock) adds the stock values in each category. COUNT(stock) would only tell you how many products there are, not how many units.', array['products']::text[]),
(134, 'medium', 'multiple-choice', 'SUM', 'You need the total number of units sold from order_items. Which aggregate gives it?', 'SUM(quantity)', '{}'::text[], array['SUM(quantity)', 'COUNT(quantity)', 'COUNT(*)', 'MAX(quantity)']::text[], null, null, null, '{}'::text[], null, 'Each line item records how many units were bought, so units sold is the sum of quantity. COUNT(quantity) and COUNT(*) only count line items, however many units each holds.', array['order_items']::text[]),
(135, 'medium', 'fix-query', 'COUNT', 'This should count customers in each tier. Fix it.', 'SELECT tier, COUNT(*) AS customer_count FROM customers GROUP BY tier', '{}'::text[], null, 'SELECT tier COUNT(*) AS customer_count FROM customers GROUP BY tier', null, null, '{}'::text[], 'Look closely at the SELECT list.', 'Items in the SELECT list must be separated by commas. Without one, PostgreSQL reads COUNT as an alias for tier and then fails at the parenthesis.', array['customers']::text[]),
(136, 'medium', 'predict-output', 'AVG', 'Average salary per department: what''s the result?', 'HR | 55000
Sales | 80000', '{}'::text[], array['HR | 55000
Sales | 80000', 'HR | 110000
Sales | 240000', 'HR | 70000
Sales | 70000', 'Sales | 80000
HR | 55000']::text[], 'SELECT department, AVG(salary) AS avg_salary
FROM employees
GROUP BY department
ORDER BY department', '[{"name":"employees","columns":["department","salary"],"rows":[["HR",50000],["HR",60000],["Sales",70000],["Sales",80000],["Sales",90000]]}]'::jsonb, null, '{}'::text[], null, 'AVG is computed separately per department: (50000 + 60000) / 2 for HR and (70000 + 80000 + 90000) / 3 for Sales. ORDER BY department puts HR first.', array['employees']::text[]),
(137, 'medium', 'drag-drop', 'SUM', 'Total salary per department, counting only London-based employees.', 'SELECT department, SUM(salary) AS london_payroll FROM employees WHERE city = ''London'' GROUP BY department', '{}'::text[], null, null, null, array['SELECT department, SUM(salary) AS london_payroll', 'FROM employees', 'WHERE city = ''London''', 'GROUP BY department']::text[], array['HAVING city = ''London''']::text[], null, 'The city test applies to each employee, so it belongs in WHERE. HAVING city = ''London'' fails because city is neither grouped nor aggregated.', array['employees']::text[]),
(138, 'medium', 'write-sql', 'AVG', 'What''s the average order value for each status? Return status and the average total_amount aliased avg_amount.', 'SELECT status, AVG(total_amount) AS avg_amount FROM orders GROUP BY status', '{}'::text[], null, null, null, null, '{}'::text[], 'Group by status, then average the amounts.', 'GROUP BY status creates one group per status value, and AVG(total_amount) is computed within each group.', array['orders']::text[]),
(139, 'medium', 'write-sql', 'INNER JOIN', 'List each order''s id with the name of the customer who placed it. Inner join orders o to customers c (orders first) and return o.id and c.name.', 'SELECT o.id, c.name FROM orders o JOIN customers c ON o.customer_id = c.id', array['SELECT o.id, c.name FROM orders o JOIN customers c ON c.id = o.customer_id']::text[], null, null, null, null, '{}'::text[], 'Match the foreign key in orders to the primary key in customers.', 'The ON clause pairs each order with the customer whose id equals its customer_id. JOIN and INNER JOIN mean the same thing in PostgreSQL.', array['customers', 'orders']::text[]),
(140, 'medium', 'multiple-choice', 'AVG', 'age is an integer column. What does AVG(age) return in PostgreSQL?', 'A numeric with decimals, e.g. 34.5', '{}'::text[], array['A numeric with decimals, e.g. 34.5', 'An integer truncated toward zero, e.g. 34', 'An integer rounded to the nearest, e.g. 35', 'An error, since AVG needs a numeric column']::text[], null, null, null, '{}'::text[], null, 'AVG of an integer column returns numeric, so fractional averages are kept. That differs from dividing two integers with /, which truncates in PostgreSQL.', '{}'::text[]),
(141, 'medium', 'fix-query', 'SUM', 'This should return the 5 customers with the highest total spend. Fix it.', 'SELECT customer_id, SUM(total_amount) AS total_spent FROM orders GROUP BY customer_id ORDER BY total_spent DESC LIMIT 5', '{}'::text[], null, 'SELECT customer_id, SUM(total_amount) AS total_spent FROM orders GROUP BY customer_id ORDER BY total_spent DESC LIMT 5', null, null, '{}'::text[], 'Check the spelling of every keyword.', 'LIMIT was misspelled. Once fixed, orders are summed per customer, sorted by total descending, and only the top five rows are kept.', array['customers', 'orders']::text[]),
(142, 'medium', 'predict-output', 'INNER JOIN', 'Order 13 points to a customer that doesn''t exist, and Ben has no orders. What does this return?', 'Ana | 30
Ana | 50
Cara | 80', '{}'::text[], array['Ana | 30
Ana | 50
Cara | 80', 'Ana | 30
Ana | 50
Cara | 80
Ben | NULL', 'Ana | 30
Cara | 80', 'NULL | 20
Ana | 30
Ana | 50
Cara | 80']::text[], 'SELECT c.name, o.total_amount
FROM customers c
JOIN orders o ON c.id = o.customer_id
ORDER BY o.total_amount', '[{"name":"customers","columns":["id","name"],"rows":[[1,"Ana"],[2,"Ben"],[3,"Cara"]]},{"name":"orders","columns":["id","customer_id","total_amount"],"rows":[[10,1,50],[11,1,30],[12,3,80],[13,4,20]]}]'::jsonb, null, '{}'::text[], null, 'An inner join keeps only matching pairs: Ben (no orders) and order 13 (no customer) both disappear. Ana matches twice, so she appears twice.', array['customers', 'orders']::text[]),
(143, 'medium', 'drag-drop', 'AVG', 'Average product price per supplier_id, rounded to 2 decimals, highest average first.', 'SELECT supplier_id, ROUND(AVG(price), 2) AS avg_price FROM products GROUP BY supplier_id ORDER BY avg_price DESC', '{}'::text[], null, null, null, array['SELECT supplier_id, ROUND(AVG(price), 2) AS avg_price', 'FROM products', 'GROUP BY supplier_id', 'ORDER BY avg_price DESC']::text[], array['ORDER BY price DESC']::text[], null, 'ORDER BY can use the output alias avg_price. Ordering by the raw price column would fail, since price is neither grouped nor aggregated.', array['products']::text[]),
(144, 'medium', 'write-sql', 'INNER JOIN', 'Show every product with its supplier. Inner join products p to suppliers s (products first); return p.name aliased product and s.name aliased supplier.', 'SELECT p.name AS product, s.name AS supplier FROM products p JOIN suppliers s ON p.supplier_id = s.id', array['SELECT p.name AS product, s.name AS supplier FROM products p JOIN suppliers s ON s.id = p.supplier_id']::text[], null, null, null, null, '{}'::text[], 'Link products.supplier_id to the supplier''s id.', 'Both tables have a name column, so each must be qualified with its table alias; the column aliases product and supplier keep the output readable.', array['products', 'suppliers']::text[]),
(145, 'medium', 'multiple-choice', 'INNER JOIN', 'In PostgreSQL, is a bare JOIN (without a type keyword) the same as INNER JOIN?', 'Yes, JOIN on its own means INNER JOIN', '{}'::text[], array['Yes, JOIN on its own means INNER JOIN', 'No, a bare JOIN means LEFT JOIN', 'No, a bare JOIN means CROSS JOIN', 'Only if both tables share a column name']::text[], null, null, null, '{}'::text[], null, 'INNER is the default join type, so JOIN and INNER JOIN are identical. Outer joins must be requested explicitly with LEFT, RIGHT or FULL.', '{}'::text[]),
(146, 'medium', 'write-sql', 'LEFT JOIN', 'List every customer with the ids of their orders, keeping customers who have no orders. Join customers c (first) to orders o; return c.name and o.id.', 'SELECT c.name, o.id FROM customers c LEFT JOIN orders o ON c.id = o.customer_id', array['SELECT c.name, o.id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id']::text[], null, null, null, null, '{}'::text[], 'Which join keeps every row of the first table?', 'LEFT JOIN keeps every row of the left table (customers). A customer with no matching order still appears once, with NULL in o.id.', array['customers', 'orders']::text[]),
(147, 'medium', 'fix-query', 'INNER JOIN', 'This should list each order''s date with the customer''s email. Fix the join.', 'SELECT o.order_date, c.email FROM orders o JOIN customers c ON o.customer_id = c.id', '{}'::text[], null, 'SELECT o.order_date, c.email FROM orders o JOIN customers c WHERE o.customer_id = c.id', null, null, '{}'::text[], 'A JOIN needs its own keyword for the join condition.', 'An INNER JOIN needs an ON (or USING) clause right after the joined table. PostgreSQL rejects a bare JOIN followed by WHERE.', array['customers', 'orders']::text[]),
(148, 'medium', 'predict-output', 'LEFT JOIN', 'What does this LEFT JOIN return?', 'Lamp | 2
Mug | NULL
Pen | 1
Pen | 5', '{}'::text[], array['Lamp | 2
Mug | NULL
Pen | 1
Pen | 5', 'Lamp | 2
Pen | 1
Pen | 5', 'Lamp | 2
Mug | 0
Pen | 1
Pen | 5', 'Lamp | 2
Mug | NULL
Pen | 6']::text[], 'SELECT p.name, oi.quantity
FROM products p
LEFT JOIN order_items oi ON p.id = oi.product_id
ORDER BY p.name, oi.quantity', '[{"name":"products","columns":["id","name"],"rows":[[1,"Lamp"],[2,"Mug"],[3,"Pen"]]},{"name":"order_items","columns":["order_id","product_id","quantity"],"rows":[[100,1,2],[101,3,5],[102,3,1]]}]'::jsonb, null, '{}'::text[], null, 'LEFT JOIN keeps every product: Mug has no line items, so it appears once with NULL. Pen matches two line items and appears twice; no aggregation happens here.', array['products', 'order_items']::text[]),
(149, 'medium', 'drag-drop', 'INNER JOIN', 'List the id and total_amount of every order placed by a Gold-tier customer.', 'SELECT o.id, o.total_amount FROM orders o JOIN customers c ON o.customer_id = c.id WHERE c.tier = ''Gold''', '{}'::text[], null, null, null, array['SELECT o.id, o.total_amount', 'FROM orders o', 'JOIN customers c ON o.customer_id = c.id', 'WHERE c.tier = ''Gold''']::text[], array['JOIN customers c ON o.id = c.id']::text[], null, 'Join each order to its customer via customer_id, then filter on the customer''s tier with WHERE. Joining o.id to c.id would match unrelated order and customer numbers.', array['customers', 'orders']::text[]),
(150, 'medium', 'multiple-choice', 'LEFT JOIN', 'In customers c LEFT JOIN orders o, what do the o columns contain for a customer with no orders?', 'NULL', '{}'::text[], array['NULL', '0 or an empty string', 'Nothing: the customer is left out', 'Values copied from another order']::text[], null, null, null, '{}'::text[], null, 'LEFT JOIN keeps every left-side row; where no right-side row matches, all of the right table''s columns are filled with NULL.', array['customers', 'orders']::text[])
on conflict (id) do nothing;

insert into public.questions (id, difficulty, type, topic, question, answer, alternatives, options, query, sample_tables, tokens, distractors, hint, explanation, schema_tables) values
(151, 'medium', 'write-sql', 'LEFT JOIN', 'List all products with their supplier''s country, keeping products whose supplier can''t be found. Join products p (first) to suppliers s; return p.name and s.country.', 'SELECT p.name, s.country FROM products p LEFT JOIN suppliers s ON p.supplier_id = s.id', array['SELECT p.name, s.country FROM products p LEFT JOIN suppliers s ON s.id = p.supplier_id']::text[], null, null, null, null, '{}'::text[], 'Keep every product, matched or not.', 'LEFT JOIN keeps every product; if no supplier matches (or supplier_id is NULL), s.country comes back as NULL instead of the product disappearing.', array['products', 'suppliers']::text[]),
(152, 'medium', 'write-sql', 'GROUP BY', 'Count employees for every department and city pair. Return department, city and the count aliased staff_count, sorted by department, then city.', 'SELECT department, city, COUNT(*) AS staff_count FROM employees GROUP BY department, city ORDER BY department, city', array['SELECT department, city, COUNT(*) AS staff_count FROM employees GROUP BY city, department ORDER BY department, city', 'SELECT department, city, COUNT(id) AS staff_count FROM employees GROUP BY department, city ORDER BY department, city']::text[], null, null, null, null, '{}'::text[], 'Both non-aggregated columns must be grouped.', 'Grouping by two columns creates one group per distinct (department, city) combination. The column order inside GROUP BY doesn''t change the groups; ORDER BY controls the output order.', array['employees']::text[]),
(153, 'medium', 'multiple-choice', 'GROUP BY', 'What does GROUP BY 1 mean in this PostgreSQL query?', 'Group by the first column in the SELECT list', '{}'::text[], array['Group by the first column in the SELECT list', 'Put all rows into one single group', 'Group by the constant 1, so it has no effect', 'Group by the table''s first column, id']::text[], 'SELECT category, COUNT(*)
FROM products
GROUP BY 1', null, null, '{}'::text[], null, 'In GROUP BY (and ORDER BY), a plain integer refers to a SELECT-list position, so GROUP BY 1 groups by category here. Handy, but naming the column is clearer.', array['products']::text[]),
(154, 'medium', 'predict-output', 'GROUP BY', 'Two products have no category. What does this return?', 'Books | 20
Toys | 8
