FROM products
GROUP BY category
ORDER BY category', '[{"name":"products","columns":["category","price"],"rows":[["Books",10],[null,5],["Books",20],["Toys",8],[null,7]]}]'::jsonb, null, '{}'::text[], null, 'GROUP BY puts all NULL categories into one group (its MAX is 7). In ascending order PostgreSQL sorts NULLs last by default.', array['products']::text[]),
(155, 'medium', 'drag-drop', 'GROUP BY', 'Count orders from 2024-01-01 onwards for each customer and status combination, largest counts first.', 'SELECT customer_id, status, COUNT(*) AS order_count FROM orders WHERE order_date >= ''2024-01-01'' GROUP BY customer_id, status ORDER BY order_count DESC', '{}'::text[], null, null, null, array['SELECT customer_id, status, COUNT(*) AS order_count', 'FROM orders', 'WHERE order_date >= ''2024-01-01''', 'GROUP BY customer_id, status', 'ORDER BY order_count DESC']::text[], array['GROUP BY customer_id']::text[], null, 'The date filter is per row, so it goes in WHERE before GROUP BY. Both customer_id and status are selected without an aggregate, so both must be grouped.', array['orders']::text[]),
(156, 'medium', 'fix-query', 'HAVING', 'This should list cities where the average employee age is under 35. Fix it.', 'SELECT city, AVG(age) AS avg_age FROM employees GROUP BY city HAVING AVG(age) < 35', '{}'::text[], null, 'SELECT city, AVG(age) AS avg_age FROM employees HAVING AVG(age) < 35 GROUP BY city', null, null, '{}'::text[], 'HAVING filters groups, so they must be formed first.', 'HAVING must come after GROUP BY: groups are formed first, then filtered. Writing HAVING before GROUP BY is a syntax error.', array['employees']::text[]),
(157, 'medium', 'write-sql', 'HAVING', 'Loyalty check: which customers have placed at least 5 orders? Return customer_id and the count aliased order_count.', 'SELECT customer_id, COUNT(*) AS order_count FROM orders GROUP BY customer_id HAVING COUNT(*) >= 5', array['SELECT customer_id, COUNT(id) AS order_count FROM orders GROUP BY customer_id HAVING COUNT(id) >= 5']::text[], null, null, null, null, '{}'::text[], 'Mind the boundary: ''at least'' includes 5.', 'Group the orders by customer, then HAVING COUNT(*) >= 5 keeps only groups with five or more rows. Using > 5 would wrongly drop customers with exactly five orders.', array['customers', 'orders']::text[]),
(158, 'medium', 'multiple-choice', 'HAVING', 'MAX(salary) isn''t in the SELECT list. Is this query valid?', 'Yes: HAVING can use aggregates that aren''t selected', '{}'::text[], array['Yes: HAVING can use aggregates that aren''t selected', 'No: MAX(salary) must also appear in SELECT', 'No: HAVING can only compare COUNT(*)', 'Only if MAX(salary) is given an alias']::text[], 'SELECT department
FROM employees
GROUP BY department
HAVING MAX(salary) > 150000', null, null, '{}'::text[], null, 'HAVING can use any aggregate over the group, whether or not it is shown. This returns departments whose top salary exceeds 150000.', array['employees']::text[]),
(159, 'medium', 'predict-output', 'HAVING', 'WHERE and HAVING together: what''s the result?', 'Books | 2', '{}'::text[], array['Books | 2', 'Books | 3
Toys | 2', 'Books | 2
Home | 1
Toys | 1', 'Books | 3']::text[], 'SELECT category, COUNT(*) AS n
FROM products
WHERE price > 20
GROUP BY category
HAVING COUNT(*) >= 2
ORDER BY category', '[{"name":"products","columns":["category","price"],"rows":[["Books",15],["Books",25],["Books",30],["Toys",22],["Toys",10],["Home",40]]}]'::jsonb, null, '{}'::text[], null, 'WHERE runs first and removes rows priced 20 or less, leaving Books with 2 rows and Toys and Home with 1 each. HAVING then keeps only groups with at least 2 rows.', array['products']::text[]),
(160, 'medium', 'write-sql', 'HAVING', 'Which product categories have an average price above 50? Return category and the average aliased avg_price.', 'SELECT category, AVG(price) AS avg_price FROM products GROUP BY category HAVING AVG(price) > 50', '{}'::text[], null, null, null, null, '{}'::text[], 'The condition is about each group''s average, not single rows.', 'AVG(price) > 50 describes a whole category, so it goes in HAVING. WHERE price > 50 would instead drop cheap products before averaging, answering a different question.', array['products']::text[]),
(161, 'medium', 'multiple-choice', 'HAVING', 'Which query lists cities that have more than 3 Gold customers?', 'SELECT city FROM customers WHERE tier = ''Gold'' GROUP BY city HAVING COUNT(*) > 3', '{}'::text[], array['SELECT city FROM customers WHERE tier = ''Gold'' GROUP BY city HAVING COUNT(*) > 3', 'SELECT city FROM customers GROUP BY city HAVING tier = ''Gold'' AND COUNT(*) > 3', 'SELECT city FROM customers WHERE tier = ''Gold'' AND COUNT(*) > 3 GROUP BY city', 'SELECT city FROM customers WHERE tier = ''Gold'' HAVING COUNT(*) > 3 GROUP BY city']::text[], null, null, null, '{}'::text[], null, 'The tier test is per row, so it goes in WHERE; the count test is per group, so it goes in HAVING after GROUP BY. Aggregates can''t appear in WHERE, and HAVING can''t use the ungrouped column tier.', array['customers']::text[]),
(162, 'medium', 'drag-drop', 'COUNT', 'For each customer, count how many different days they placed orders on, most active first.', 'SELECT customer_id, COUNT(DISTINCT order_date) AS order_days FROM orders GROUP BY customer_id ORDER BY order_days DESC', '{}'::text[], null, null, null, array['SELECT customer_id, COUNT(DISTINCT order_date) AS order_days', 'FROM orders', 'GROUP BY customer_id', 'ORDER BY order_days DESC']::text[], array['SELECT customer_id, DISTINCT COUNT(order_date) AS order_days']::text[], null, 'DISTINCT goes inside the parentheses: COUNT(DISTINCT order_date) counts unique dates per customer. Writing DISTINCT COUNT(order_date) after another column is a syntax error.', array['orders']::text[]),
(163, 'medium', 'fix-query', 'SUM', 'This should show the total stock of Electronics products per supplier_id. Fix it.', 'SELECT supplier_id, SUM(stock) AS units FROM products WHERE category = ''Electronics'' GROUP BY supplier_id', '{}'::text[], null, 'SELECT supplier_id, SUM(stock) AS units FROM products WHERE category = ''Electronics'' GROUP BY category', null, null, '{}'::text[], 'What should each output row represent?', 'Group by what each output row represents: supplier_id. Grouping by category leaves supplier_id ungrouped and unaggregated, which PostgreSQL rejects.', array['products']::text[]),
(164, 'medium', 'write-sql', 'COUNT', 'For each supplier_id, in how many distinct categories does it sell products? Return supplier_id and the count aliased category_count.', 'SELECT supplier_id, COUNT(DISTINCT category) AS category_count FROM products GROUP BY supplier_id', '{}'::text[], null, null, null, null, '{}'::text[], 'Group by supplier, and count each category only once.', 'COUNT(DISTINCT category) is evaluated per supplier group, so a supplier with ten Books products still counts Books only once.', array['products']::text[]),
(165, 'medium', 'multiple-choice', 'COUNT', 'No order has the status ''returned''. What does this return?', 'One row containing 0', '{}'::text[], array['One row containing 0', 'One row containing NULL', 'No rows at all', 'An error: unknown status value']::text[], 'SELECT COUNT(*) FROM orders
WHERE status = ''returned''', null, null, '{}'::text[], null, 'An aggregate without GROUP BY always returns exactly one row. COUNT over zero rows is 0, unlike SUM, AVG, MIN and MAX, which return NULL on empty input.', array['orders']::text[]),
(166, 'medium', 'predict-output', 'COUNT', 'What does this count for each status?', 'pending | 1
shipped | 2', '{}'::text[], array['pending | 1
shipped | 2', 'pending | 2
shipped | 3', 'shipped | 2
pending | 1', '3']::text[], 'SELECT status, COUNT(DISTINCT customer_id) AS buyers
FROM orders
GROUP BY status
ORDER BY status', '[{"name":"orders","columns":["customer_id","status"],"rows":[[1,"shipped"],[1,"shipped"],[2,"shipped"],[3,"pending"],[3,"pending"]]}]'::jsonb, null, '{}'::text[], null, 'COUNT(DISTINCT customer_id) counts different customers per status, not orders: shipped has customers 1 and 2, pending only customer 3.', array['orders']::text[]),
(167, 'medium', 'drag-drop', 'SUM', 'Total spend per customer_id, computed from line items by joining orders o to order_items oi.', 'SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spend FROM orders o JOIN order_items oi ON o.id = oi.order_id GROUP BY o.customer_id', '{}'::text[], null, null, null, array['SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spend', 'FROM orders o', 'JOIN order_items oi ON o.id = oi.order_id', 'GROUP BY o.customer_id']::text[], array['JOIN order_items oi ON o.customer_id = oi.order_id']::text[], null, 'Each line item belongs to an order via oi.order_id = o.id; SUM then adds the line values per customer. Joining on customer_id would pair unrelated rows.', array['orders', 'order_items']::text[]),
(168, 'medium', 'write-sql', 'SUM', 'Using order_items, compute each order''s value. Return order_id and the sum of quantity * unit_price aliased order_value.', 'SELECT order_id, SUM(quantity * unit_price) AS order_value FROM order_items GROUP BY order_id', '{}'::text[], null, null, null, null, '{}'::text[], 'An aggregate can take an expression, not just a column.', 'SUM(quantity * unit_price) computes each line''s value first, then adds the lines per order. SUM(quantity) * SUM(unit_price) would multiply the totals and overstate the value.', array['order_items']::text[]),
(169, 'medium', 'multiple-choice', 'SUM', 'What''s the difference between SUM(price) and SUM(DISTINCT price)?', 'SUM(DISTINCT price) adds each different price only once', '{}'::text[], array['SUM(DISTINCT price) adds each different price only once', 'SUM(DISTINCT price) returns how many distinct prices exist', 'SUM(DISTINCT price) is not valid in PostgreSQL', 'None; both always return the same total']::text[], null, null, null, '{}'::text[], null, 'DISTINCT inside an aggregate removes duplicate values first, so two products priced 10 contribute 10, not 20. It''s rarely what you want for real totals.', '{}'::text[]),
(170, 'medium', 'fix-query', 'AVG', 'This should return the average salary of employees who have a manager, but it returns NULL. Fix it.', 'SELECT AVG(salary) AS avg_salary FROM employees WHERE manager_id IS NOT NULL', '{}'::text[], null, 'SELECT AVG(salary) AS avg_salary FROM employees WHERE manager_id != NULL', null, null, '{}'::text[], 'Comparing anything to NULL with != is never true.', 'Any comparison with NULL (=, !=, <>) yields NULL, so WHERE drops every row and AVG over no rows is NULL. Test for missing values with IS NULL / IS NOT NULL.', array['employees']::text[]),
(171, 'medium', 'predict-output', 'SUM', 'Some totals are missing (NULL). What does this return?', 'delivered | 75
pending | NULL
shipped | 100', '{}'::text[], array['delivered | 75
pending | NULL
shipped | 100', 'delivered | 75
pending | 0
shipped | 100', 'delivered | 75
shipped | 100', 'delivered | 75
pending | NULL
shipped | NULL']::text[], 'SELECT status, SUM(total_amount) AS revenue
FROM orders
GROUP BY status
ORDER BY status', '[{"name":"orders","columns":["status","total_amount"],"rows":[["shipped",100],["shipped",null],["pending",null],["delivered",50],["delivered",25]]}]'::jsonb, null, '{}'::text[], null, 'SUM skips NULLs, so shipped is 100. But pending has only a NULL, and SUM of no non-NULL values is NULL, not 0. The group still appears.', array['orders']::text[]),
(172, 'medium', 'write-sql', 'AVG', 'Show each department''s average employee age, rounded to 1 decimal place with ROUND. Return department and the rounded value aliased avg_age.', 'SELECT department, ROUND(AVG(age), 1) AS avg_age FROM employees GROUP BY department', '{}'::text[], null, null, null, null, '{}'::text[], 'Round the finished average, not the individual ages.', 'AVG of an integer column returns a numeric with many decimals; ROUND(AVG(age), 1) rounds the final result. AVG(ROUND(age, 1)) would round the inputs instead, which does nothing useful here.', array['employees']::text[]),
(173, 'medium', 'multiple-choice', 'AVG', 'price may contain NULLs. Which expression always equals AVG(price)?', 'SUM(price) / COUNT(price)', '{}'::text[], array['SUM(price) / COUNT(price)', 'SUM(price) / COUNT(*)', 'SUM(DISTINCT price) / COUNT(price)', '(MAX(price) + MIN(price)) / 2']::text[], null, null, null, '{}'::text[], null, 'AVG ignores NULLs in both the total and the count, which is exactly SUM(price) / COUNT(price). Dividing by COUNT(*) would include NULL rows and drag the average down.', '{}'::text[]),
(174, 'medium', 'drag-drop', 'AVG', 'Average age per Engineering job title, only for titles held by at least 3 people.', 'SELECT job_title, AVG(age) AS avg_age FROM employees WHERE department = ''Engineering'' GROUP BY job_title HAVING COUNT(*) >= 3', '{}'::text[], null, null, null, array['SELECT job_title, AVG(age) AS avg_age', 'FROM employees', 'WHERE department = ''Engineering''', 'GROUP BY job_title', 'HAVING COUNT(*) >= 3']::text[], array['HAVING department = ''Engineering''']::text[], null, 'The department test is per row (WHERE), while ''at least 3 people'' is per group (HAVING COUNT(*) >= 3). HAVING can use an aggregate that isn''t in the SELECT list.', array['employees']::text[]),
(175, 'medium', 'predict-output', 'AVG', 'One Finance employee has no age recorded. What''s the output?', 'Finance | 35
Marketing | 28', '{}'::text[], array['Finance | 35
Marketing | 28', 'Finance | 23.33
